-- Disposable QA inventory. Every exposed security-definer signature is explicit.
do $$begin if current_database() !~ '^nello_qa_wave02_[0-9]+$' or current_user<>'supabase_admin' then raise exception 'isolated_qa_required';end if;end$$;
create temporary table wave02_client_rpc_contract(signature text primary key,anonymous boolean,authenticated boolean,config text[],definition_md5 text);
alter table wave02_client_rpc_contract add column body_only boolean not null default false;
create function pg_temp.assert_client_rpc_surface() returns void language plpgsql set search_path=public,extensions as $$begin
if exists(select 1 from wave02_client_rpc_contract c left join pg_proc p on p.oid=to_regprocedure('public.'||c.signature) where p.oid is null or not p.prosecdef or p.proconfig is distinct from c.config or md5(replace(case when c.body_only then p.prosrc else pg_get_functiondef(p.oid) end,E'\r\n',E'\n'))<>c.definition_md5 or has_function_privilege('anon',p.oid,'execute') is distinct from c.anonymous or has_function_privilege('authenticated',p.oid,'execute') is distinct from c.authenticated) then raise exception 'client_rpc_signature_acl_settings_or_body_drift:%', (select jsonb_agg(jsonb_build_object('signature',c.signature,'exists',p.oid is not null,'config',p.proconfig,'expected_md5',c.definition_md5,'actual_md5',md5(replace(case when c.body_only then p.prosrc else pg_get_functiondef(p.oid) end,E'\r\n',E'\n')))) from wave02_client_rpc_contract c left join pg_proc p on p.oid=to_regprocedure('public.'||c.signature) where p.oid is null or not p.prosecdef or p.proconfig is distinct from c.config or md5(replace(case when c.body_only then p.prosrc else pg_get_functiondef(p.oid) end,E'\r\n',E'\n'))<>c.definition_md5 or has_function_privilege('anon',p.oid,'execute') is distinct from c.anonymous or has_function_privilege('authenticated',p.oid,'execute') is distinct from c.authenticated);end if;
if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef and (has_function_privilege('anon',p.oid,'execute') or has_function_privilege('authenticated',p.oid,'execute')) and not exists(select 1 from wave02_client_rpc_contract c where to_regprocedure('public.'||c.signature)=p.oid)) then raise exception 'unreviewed_client_rpc_added';end if;
end$$;
select pg_temp.assert_client_rpc_surface();
